import{_ as i,C as a,o as n,c as h,j as t,a as c,E as e,aj as r}from"./chunks/framework.DkvuVDKz.js";const v=JSON.parse('{"title":"ColorSlider 颜色滑块","description":"","frontmatter":{},"headers":[],"relativePath":"components/color-slider.md","filePath":"components/color-slider.md","lastUpdated":1789421164000}'),s={name:"components/color-slider.md"},b={id:"colorslider-颜色滑块",tabindex:"-1"};function u(p,d,g,m,x,f){const l=a("Badge"),o=a("XhDemo");return n(),h("div",null,[t("h1",b,[d[0]||(d[0]=c("ColorSlider 颜色滑块 ",-1)),e(l,{type:"info",text:"alpha"}),d[1]||(d[1]=c()),d[2]||(d[2]=t("a",{class:"header-anchor",href:"#colorslider-颜色滑块","aria-label":'Permalink to "ColorSlider 颜色滑块 <Badge type="info" text="alpha" />"'},"​",-1))]),d[3]||(d[3]=r('<p>一条只推颜色某一路的滑杆：色相、饱和度、明度、透明度，或红、绿、蓝。值是整个颜色串，轨道画的是这一路从头走到尾会变成什么颜色，拇指填的是当下那一档。 把几条并排就是一个自己拼出来的调色面板；<a href="./color-picker">颜色选择器</a>浮层里的色相带与透明度带就是它。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/color-slider" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/color-slider.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/color-slider" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/color-slider" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/color-slider.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>一条滑杆只推颜色的一路，默认是色相：值是整个颜色串，轨道画的是这一路从头走到尾的颜色</p>',4)),e(o,{src:"color-slider/01-basic"}),d[4]||(d[4]=r('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;color-slider&quot;</code>：<code>root</code> · <code>label</code> · <strong><code>control</code></strong> · <strong><code>track</code></strong> · <strong><code>thumb</code></strong> · <code>value-text</code> · <code>hidden-input</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="通道并排" tabindex="-1">通道并排 <a class="header-anchor" href="#通道并排" aria-label="Permalink to &quot;通道并排&quot;">​</a></h3><p>几条共用同一个值、各推自己那一路；开 alpha 让推色相时透明度不丢，就拼出一个 HSV 调色面板</p>',6)),e(o,{src:"color-slider/02-channels"}),d[5]||(d[5]=t("h3",{id:"红绿蓝与写法",tabindex:"-1"},[c("红绿蓝与写法 "),t("a",{class:"header-anchor",href:"#红绿蓝与写法","aria-label":'Permalink to "红绿蓝与写法"'},"​")],-1)),d[6]||(d[6]=t("p",null,"推 RGB 三路走 0-255；format 决定写回的写法，这里按 rgba() 输出",-1)),e(o,{src:"color-slider/03-rgb"}),d[7]||(d[7]=t("h3",{id:"竖直与状态",tabindex:"-1"},[c("竖直与状态 "),t("a",{class:"header-anchor",href:"#竖直与状态","aria-label":'Permalink to "竖直与状态"'},"​")],-1)),d[8]||(d[8]=t("p",null,"orientation 竖排时渐变自下而上；禁用整体压暗，只读留 Tab 位但推不动",-1)),e(o,{src:"color-slider/04-states"}),d[9]||(d[9]=r('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>用户只需要调颜色的某一个分量：透明度、明暗、色相。</li><li>把几条并排，按 HSV 或 RGB 自己拼一个内嵌的调色面板，不要浮层。</li><li>要在页面上常驻、随时可拖的颜色调节，而不是点开再选。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>用户要在色域里自由取色：用<a href="./color-picker">颜色选择器</a>，它带二维取色区。</li><li>只是从几个固定颜色里挑一个：用<a href="./color-swatch-picker">颜色色块选择器</a>。</li><li>推的是一个普通数值：用<a href="./slider">滑块</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li><code>channel</code> 七选一：<code>hue</code>（0-360）、<code>saturation</code> / <code>brightness</code> / <code>alpha</code>（0-100）、<code>red</code> / <code>green</code> / <code>blue</code>（0-255）；步长 1，PageUp / PageDown 走 10。</li><li>值恒是整个颜色串，<code>format</code> 决定写法（hex / rgba / hsla）；<code>alpha</code> 决定串里带不带透明度，缺省时推透明度那一路带、其余不带——与一条透明度滑块并排时显式开它，否则推色相会把透明度归 1。</li><li>轨道渐变由连接层按当前颜色现算：其余分量不动，只让本通道从 min 走到 max；透明度那一路从全透明走到实色，棋盘格垫在底下。</li><li>灰度与纯黑处色相无定义，把明度推到 0 再拉回来，色相靠锚保住不塌成 0。</li><li>拖动、键盘、RTL 掉头与竖直排布整份取自内嵌的<a href="./slider">滑块</a>；<code>onValueChange</code> 拖动中连发，<code>onValueChangeEnd</code> 松手只发一次。</li><li>拇指按未取整的工作色定位，比按整格算的更贴当前颜色；<code>aria-valuetext</code> 带单位播报。</li><li>尺寸 sm / md / lg 换的是拇指直径与颜色带厚度；禁用整体压暗，只读留 Tab 位但推不动，<code>invalid</code> 只换拇指描边（面要保住当前颜色）。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>放进<a href="./field">表单字段</a>里：标签、说明与错误由字段渲出来并经 aria-describedby 念到拇指上，禁用 / 只读 / 无效三轴随字段下发。</li><li>与<a href="./color-swatch">颜色色块</a>并排：色块显示整个颜色，滑块推其中一路。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>并排多条时共用同一个值，每条只改自己那一路；开 <code>alpha</code> 让透明度在别的通道推动时不丢。</li><li>给 <code>label</code> 部件或 <code>translations.label</code>：一条渐变带自己说不出它调的是什么。</li><li>需要落库时监听 <code>onValueChangeEnd</code>，拖动途中的连发只用来预览。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>拿它调普通数值：渐变、单位与区间都按颜色通道定死，改不成别的尺。</li><li>传颜色关键字（<code>red</code>）：不在支持的写法里，会被当成无效值原地不动。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-color-slider&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhColorSliderControl</code> <code>XhColorSliderHiddenInput</code> <code>XhColorSliderLabel</code> <code>XhColorSliderRoot</code> <code>XhColorSliderThumb</code> <code>XhColorSliderTrack</code> <code>XhColorSliderValueText</code></td></tr><tr><td>组合式函数</td><td><code>useColorSlider</code></td></tr><tr><td>状态机</td><td><code>colorSliderMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/color-slider.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string</code></td><td></td><td>颜色值串。给定即受控：cell 直读 prop，写只发 onValueChange 不落内部值。</td></tr><tr><td><code>defaultValue</code></td><td><code>string</code></td><td></td><td></td></tr><tr><td><code>channel</code></td><td><code>ColorChannel</code></td><td></td><td>推的是哪一路：色相 / 饱和度 / 明度 / 透明度 / 红 / 绿 / 蓝，默认 hue。</td></tr><tr><td><code>format</code></td><td><code>ColorFormat</code></td><td></td><td>值串的写法，默认 hex。改它只改对外的序列化，工作色恒是 HSVA。</td></tr><tr><td><code>hsva</code></td><td><code>ColorHsva</code></td><td></td><td>受控的工作色。给定时本通道以外的分量、灰度处的色相都以它为准，不再从值串反解： 取色器把同一份工作色交给几条并排的滑块，推色相那条时饱和度与明度不会被值串抹掉。 单独用一条滑块时不必给，滑块自己记着锚。</td></tr><tr><td><code>alpha</code></td><td><code>boolean</code></td><td></td><td>值串带不带透明度。默认跟着通道走：推透明度那一路时带，其余不带。 显式给 true 时别的通道也保留透明度（与一条透明度滑块并排时要开它，否则推色相会把透明度归 1）。</td></tr><tr><td><code>orientation</code></td><td><code>Orientation</code></td><td></td><td></td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向。只改写水平轨道上左右两键与指针的语义。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>invalid</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，决定拇指直径与轨道厚度。</td></tr><tr><td><code>name</code></td><td><code>string</code></td><td></td><td>表单字段名；给了表单影子才带 name 并参与提交。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;ColorSliderTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onValueChange</code></td><td><code>(details: ColorSliderValueChangeDetails) =&gt; void</code></td><td></td><td>value 变化意图回调；受控时是唯一出口，非受控随内部写入一并通知。拖动过程中会连续发。</td></tr><tr><td><code>onValueChangeEnd</code></td><td><code>(details: ColorSliderValueChangeDetails) =&gt; void</code></td><td></td><td>只在一次操作结束时发一次，适合拿来发请求。</td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>value-change</code></td><td><code>ColorSliderValueChangeDetails</code></td><td>颜色变化；detail 为 <code>{ value: string }</code>，拖动过程中会连续发</td></tr><tr><td><code>value-change-end</code></td><td><code>ColorSliderValueChangeDetails</code></td><td>一次推动结束；detail 为 <code>{ value: string }</code></td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhColorSliderRoot</code></td><td><code>default</code></td><td><code>ColorSliderRootSlotProps</code></td><td></td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>VALUE.SET</code> · <code>CHANNEL.SET</code> · <code>CHANGE.END</code> · <code>FORM.RESET</code></p><p><strong>判据</strong>：<code>canInteract</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string</code></td><td>当前值串（与 onValueChange 送出的是同一个）。</td></tr><tr><td><code>channel</code></td><td><code>ColorChannel</code></td><td></td></tr><tr><td><code>channelValue</code></td><td><code>number</code></td><td>本通道此刻的对外数值（色相是角度，饱和度 / 明度 / 透明度是百分数，红绿蓝是 0-255）。</td></tr><tr><td><code>percent</code></td><td><code>number</code></td><td>值在轨道上的位置，0-1。按未取整的工作色算，比滑杆按整格算的那一份更贴当前颜色。</td></tr><tr><td><code>min</code></td><td><code>number</code></td><td></td></tr><tr><td><code>max</code></td><td><code>number</code></td><td></td></tr><tr><td><code>hsva</code></td><td><code>ColorHsva</code></td><td></td></tr><tr><td><code>rgba</code></td><td><code>ColorRgba</code></td><td></td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>dragging</code></td><td><code>boolean</code></td><td>指针正拖着拇指。</td></tr><tr><td><code>setValue</code></td><td><code>(next: string) =&gt; void</code></td><td></td></tr><tr><td><code>setChannelValue</code></td><td><code>(next: number) =&gt; void</code></td><td>直接把本通道推到某个对外数值。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLabelProps</code></td><td><code>() =&gt; T[&#39;label&#39;]</code></td><td></td></tr><tr><td><code>getControlProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTrackProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>轨道：渐变由连接层按当前颜色现算写成内联 background-image。</td></tr><tr><td><code>getThumbProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getValueTextProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getHiddenInputProps</code></td><td><code>() =&gt; T[&#39;input&#39;]</code></td><td>表单影子：值随表单提交。给了 name 才带 name，不给就不参与提交。</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/slider/" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>ArrowRight</code> / <code>ArrowUp</code></td><td>focus in thumb, not disabled/readOnly</td><td>本通道按 step 增大；RTL 与竖直排布下按屏幕方向对调，语义恒是&quot;朝 max 走一格&quot;</td></tr><tr><td><code>ArrowLeft</code> / <code>ArrowDown</code></td><td>focus in thumb, not disabled/readOnly</td><td>本通道按 step 减小，同上对调规则</td></tr><tr><td><code>PageUp</code></td><td>focus in thumb, not disabled/readOnly</td><td>按 largeStep 增大（各通道均为 10 格）</td></tr><tr><td><code>PageDown</code></td><td>focus in thumb, not disabled/readOnly</td><td>按 largeStep 减小</td></tr><tr><td><code>Home</code></td><td>focus in thumb, not disabled/readOnly</td><td>取本通道的 min</td></tr><tr><td><code>End</code></td><td>focus in thumb, not disabled/readOnly</td><td>取本通道的 max</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>thumb</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>thumb</code></td><td><code>aria-label</code></td><td>label.label(channel)</td></tr><tr><td><code>thumb</code></td><td><code>aria-labelledby</code></td><td><code>label</code> 部件的 id</td></tr><tr><td><code>thumb</code></td><td><code>aria-orientation</code></td><td>props.orientation</td></tr><tr><td><code>thumb</code></td><td><code>aria-valuemax</code></td><td>String(range.max)</td></tr><tr><td><code>thumb</code></td><td><code>aria-valuemin</code></td><td>String(range.min)</td></tr><tr><td><code>thumb</code></td><td><code>aria-valuenow</code></td><td>String(channelValue)</td></tr><tr><td><code>thumb</code></td><td><code>aria-valuetext</code></td><td>label.valueText(channel, channelValue)</td></tr><tr><td><code>thumb</code></td><td><code>role</code></td><td>&#39;slider&#39;</td></tr><tr><td><code>value-text</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/color-slider.css</code> 使用 <code>[data-scope=&quot;color-slider&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-value</code></td><td>context.get(&#39;value&#39;)</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；缺省来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>缺省来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-color-slider-checker</code></td><td><code>track</code></td><td><code>background-image</code></td><td><code>channel=alpha</code></td><td><code>--xh-color-neutral-300</code></td><td>color-slider 的 track 部件 background-image 覆盖槽。</td></tr><tr><td><code>--xh-color-slider-checker-base</code></td><td><code>track</code></td><td><code>background-color</code></td><td><code>channel=alpha</code></td><td><code>--xh-bg-surface</code></td><td>color-slider 的 track 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-color-slider-gap</code></td><td><code>root</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-stack-gap-md</code></td><td>color-slider 的 root 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-color-slider-label-fg</code></td><td><code>label</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-muted</code></td><td>color-slider 的 label 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-color-slider-label-font-size</code></td><td><code>label</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-text-label-size</code></td><td>color-slider 的 label 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-color-slider-label-font-weight</code></td><td><code>label</code></td><td><code>font-weight</code></td><td><code>default</code></td><td><code>--xh-text-label-weight</code></td><td>color-slider 的 label 部件 font-weight 覆盖槽。</td></tr><tr><td><code>--xh-color-slider-thumb-bg</code></td><td><code>thumb</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-_color-slider-thumb-color</code></td><td>color-slider 的 thumb 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-color-slider-thumb-border</code></td><td><code>thumb</code></td><td><code>border</code></td><td><code>default</code></td><td><code>--xh-bg-surface</code></td><td>color-slider 的 thumb 部件 border 覆盖槽。</td></tr><tr><td><code>--xh-color-slider-thumb-border-invalid</code></td><td><code>thumb</code></td><td><code>border-color</code></td><td><code>invalid</code></td><td><code>--xh-border-invalid</code></td><td>color-slider 的 thumb 部件 border-color 覆盖槽。</td></tr><tr><td><code>--xh-color-slider-thumb-radius</code></td><td><code>thumb</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-pill</code></td><td>color-slider 的 thumb 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-color-slider-thumb-scale-dragging</code></td><td><code>thumb</code></td><td><code>scale</code></td><td><code>dragging</code></td><td><code>--xh-motion-scale-drag</code></td><td>color-slider 的 thumb 部件 scale 覆盖槽。</td></tr><tr><td><code>--xh-color-slider-thumb-shadow</code></td><td><code>thumb</code></td><td><code>box-shadow</code></td><td><code>default</code></td><td><code>--xh-elevation-raised</code></td><td>color-slider 的 thumb 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-color-slider-thumb-shadow-dragging</code></td><td><code>thumb</code></td><td><code>box-shadow</code></td><td><code>dragging</code></td><td><code>--xh-elevation-lifted</code></td><td>color-slider 的 thumb 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-color-slider-thumb-size</code></td><td><code>control</code><br><code>root</code><br><code>thumb</code></td><td><code>block-size</code><br><code>inline-size</code><br><code>margin-block-end</code><br><code>margin-block-start</code><br><code>margin-inline-start</code></td><td><code>default</code><br><code>orientation=horizontal</code><br><code>orientation=vertical</code><br><code>size=lg</code><br><code>size=sm</code></td><td><code>--xh-space-3</code><br><code>--xh-space-6</code><br><code>--xh-track-thumb-size</code></td><td>color-slider 的 control、root、thumb 部件 block-size、inline-size、margin-block-end、margin-block-start、margin-inline-start 覆盖槽。</td></tr><tr><td><code>--xh-color-slider-track-border</code></td><td><code>track</code></td><td><code>box-shadow</code></td><td><code>default</code></td><td><code>--xh-border-subtle</code></td><td>color-slider 的 track 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-color-slider-track-radius</code></td><td><code>track</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-pill</code></td><td>color-slider 的 track 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-color-slider-track-thickness</code></td><td><code>control</code><br><code>root</code><br><code>track</code></td><td><code>block-size</code><br><code>inline-size</code></td><td><code>default</code><br><code>orientation=horizontal</code><br><code>orientation=vertical</code><br><code>size=lg</code><br><code>size=sm</code></td><td><code>--xh-space-2</code><br><code>--xh-space-3</code><br><code>--xh-space-4</code></td><td>color-slider 的 control、root、track 部件 block-size、inline-size 覆盖槽。</td></tr><tr><td><code>--xh-color-slider-value-text-bg</code></td><td><code>value-text</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-bg-brand</code></td><td>color-slider 的 value-text 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-color-slider-value-text-fg</code></td><td><code>value-text</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-on-brand</code></td><td>color-slider 的 value-text 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-color-slider-value-text-font-size</code></td><td><code>value-text</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-text-caption-size</code></td><td>color-slider 的 value-text 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-color-slider-value-text-offset</code></td><td><code>value-text</code></td><td><code>margin-block-end</code><br><code>margin-inline</code></td><td><code>default</code><br><code>orientation=vertical</code></td><td><code>--xh-space-2</code></td><td>color-slider 的 value-text 部件 margin-block-end、margin-inline 覆盖槽。</td></tr><tr><td><code>--xh-color-slider-value-text-px</code></td><td><code>value-text</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-space-2</code></td><td>color-slider 的 value-text 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-color-slider-value-text-py</code></td><td><code>value-text</code></td><td><code>padding-block</code></td><td><code>default</code></td><td><code>--xh-space-0_5</code></td><td>color-slider 的 value-text 部件 padding-block 覆盖槽。</td></tr><tr><td><code>--xh-color-slider-value-text-radius</code></td><td><code>value-text</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-control</code></td><td>color-slider 的 value-text 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-color-slider-vertical-length</code></td><td><code>control</code></td><td><code>block-size</code></td><td><code>orientation=vertical</code></td><td><code>--xh-overlay-menu-min-w</code></td><td>color-slider 的 control 部件 block-size 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p><code>box-shadow</code> · <code>opacity</code> · <code>scale</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p><code>prefers-reduced-motion: reduce</code> 下本组件另有降级规则。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p>',54))])}const q=i(s,[["render",u]]);export{v as __pageData,q as default};
